#!/usr/bin/env node
// Packs Blender output (tools/athletes/build) into shipped runtime assets (public/athletes):
// - glTF: dedup, weld, quantize and EXT_meshopt_compression (gltf-transform + meshoptimizer);
// - textures: KTX2 via toktx (UASTC + zstd for normal maps, ETC1S for color and masks);
// - content-hashed file names, manifest.json, LICENSES.md, sources.lock.json, the Basis transcoder.
// Files no longer referenced by the manifest are deleted.
import { createHash } from 'node:crypto'
import { copyFileSync, existsSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs'
import { execFileSync } from 'node:child_process'
import path from 'node:path'
import { NodeIO } from '@gltf-transform/core'
import { ALL_EXTENSIONS } from '@gltf-transform/extensions'
import { dedup, meshopt, prune, weld } from '@gltf-transform/functions'
import { MeshoptDecoder, MeshoptEncoder } from 'meshoptimizer'
import { BUILD, KTX_ENV, LOCK, PUBLIC_ATHLETES, PUBLIC_BASIS, ROOT, TOKTX, TOOL_DIR } from './lib/paths.mjs'
import { rawToDocument } from './lib/raw.mjs'

const contract = JSON.parse(readFileSync(path.join(TOOL_DIR, 'contract.json'), 'utf8'))
const sha = (buf) => createHash('sha256').update(buf).digest('hex')
const rel = (p) => path.relative(PUBLIC_ATHLETES, p).split(path.sep).join('/')

await MeshoptEncoder.ready
await MeshoptDecoder.ready
const io = new NodeIO().registerExtensions(ALL_EXTENSIONS).registerDependencies({ 'meshopt.encoder': MeshoptEncoder, 'meshopt.decoder': MeshoptDecoder })

function readMetas() {
  const dir = path.join(BUILD, 'meta')
  if (!existsSync(dir)) return []
  return readdirSync(dir)
    .filter((f) => f.endsWith('.json'))
    .sort()
    .map((f) => JSON.parse(readFileSync(path.join(dir, f), 'utf8')))
}

function writeHashed(dir, base, ext, buf) {
  mkdirSync(dir, { recursive: true })
  const h = sha(buf)
  const file = path.join(dir, `${base}.${h.slice(0, 10)}${ext}`)
  if (!existsSync(file)) writeFileSync(file, buf)
  return { file: rel(file), bytes: buf.length, sha256: h }
}

async function packGlb(src, outDir, name) {
  const doc = src.endsWith('.json') ? rawToDocument(src) : await io.read(src)
  const root = doc.getRoot()
  for (const a of root.listAnimations()) a.dispose()
  for (const m of root.listMaterials()) m.dispose()
  for (const t of root.listTextures()) t.dispose()
  // keepAttributes: materials are stripped, so prune must not drop UVs and tangents the runtime needs
  await doc.transform(dedup(), weld(), prune({ keepAttributes: true, keepLeaves: true }), meshopt({ encoder: MeshoptEncoder, level: 'high' }))
  const meshes = []
  let triangles = 0
  let vertices = 0
  let primitives = 0
  for (const mesh of root.listMeshes()) {
    const names = mesh.getExtras()?.targetNames ?? []
    for (const p of mesh.listPrimitives()) {
      const idx = p.getIndices()
      const pos = p.getAttribute('POSITION')
      triangles += Math.floor((idx ? idx.getCount() : pos.getCount()) / 3)
      vertices += pos.getCount()
      primitives++
    }
    meshes.push({ name: mesh.getName(), morphs: names })
  }
  const joints = root.listSkins().flatMap((s) => s.listJoints().map((j) => j.getName()))
  const buf = Buffer.from(await io.writeBinary(doc))
  return { ...writeHashed(outDir, name, '.glb', buf), triangles, vertices, primitives, meshes, joints: [...new Set(joints)] }
}

const ktxCache = path.join(BUILD, '.ktx-cache')
function packTexture(src, outDir, name, opts) {
  const input = readFileSync(src)
  const flags =
    opts.codec === 'uastc'
      ? ['--t2', '--encode', 'uastc', '--uastc_quality', '2', '--zcmp', '18', '--genmipmap', '--assign_oetf', 'linear']
      : ['--t2', '--encode', 'etc1s', '--clevel', '4', '--qlevel', String(opts.quality ?? 192), '--genmipmap', '--assign_oetf', opts.srgb ? 'srgb' : 'linear']
  const key = sha(Buffer.concat([input, Buffer.from(JSON.stringify(flags))])).slice(0, 24)
  mkdirSync(ktxCache, { recursive: true })
  const cached = path.join(ktxCache, key + '.ktx2')
  if (!existsSync(cached)) {
    if (!existsSync(TOKTX)) throw new Error('toktx missing: run pnpm athletes:fetch')
    execFileSync(TOKTX, [...flags, cached, src], { env: KTX_ENV, stdio: ['ignore', 'ignore', 'inherit'] })
  }
  return { ...writeHashed(outDir, name, '.ktx2', readFileSync(cached)), codec: opts.codec, srgb: !!opts.srgb }
}

const metas = readMetas()
if (!metas.length) throw new Error('no build output: run the Blender stage first (pnpm athletes:build)')
const rig = JSON.parse(readFileSync(path.join(BUILD, 'rig.json'), 'utf8'))
const rigNames = rig.bones.map((b) => b.name)

const manifest = {
  $comment: 'Generated by tools/athletes/pack.mjs. Do not edit; regenerate with pnpm athletes:build.',
  version: contract.version,
  bones: rigNames,
  levels: {},
  license: { summary: 'All athlete assets are CC0-1.0: derived from MakeHuman CC0 assets or generated by the in-repo toolchain.', file: 'LICENSES.md', sources: 'sources.lock.json' },
}

for (const level of contract.levels) {
  const outDir = path.join(PUBLIC_ATHLETES, level)
  const assets = {}
  const textures = {}
  let bytes = 0
  for (const meta of metas) {
    const lv = meta.levels?.[level]
    if (!lv) continue
    const glb = await packGlb(path.join(BUILD, lv.raw ?? lv.glb), outDir, meta.name)
    const texRefs = {}
    for (const [key, t] of Object.entries(lv.textures ?? {})) {
      // shared textures are packed once per level under their file stem
      const stem = path.basename(t.file, path.extname(t.file))
      textures[stem] ??= packTexture(path.join(BUILD, t.file), path.join(outDir, 'tex'), stem, t)
      texRefs[key] = stem
    }
    assets[meta.name] = {
      slot: meta.slot ?? meta.kind,
      variant: meta.variant ?? null,
      license: meta.license,
      glb: { file: glb.file, bytes: glb.bytes, sha256: glb.sha256 },
      triangles: glb.triangles,
      vertices: glb.vertices,
      drawCalls: glb.primitives,
      meshes: glb.meshes,
      joints: glb.joints,
      textures: texRefs,
      extras: lv.extras ?? meta.extras ?? {},
    }
    bytes += glb.bytes
  }
  for (const t of Object.values(textures)) bytes += t.bytes
  if (Object.keys(assets).length) manifest.levels[level] = { bytes, assets, textures }
}

mkdirSync(PUBLIC_ATHLETES, { recursive: true })
writeFileSync(path.join(PUBLIC_ATHLETES, 'manifest.json'), JSON.stringify(manifest, null, 2) + '\n')

// licenses and provenance
const lock = JSON.parse(readFileSync(LOCK, 'utf8'))
copyFileSync(LOCK, path.join(PUBLIC_ATHLETES, 'sources.lock.json'))
const mh = lock.items.makehuman
const sys = lock.items.systemAssets
writeFileSync(
  path.join(PUBLIC_ATHLETES, 'LICENSES.md'),
  `# Athlete asset licenses

Generated by \`tools/athletes/pack.mjs\`.

## Shipped athlete assets (\`public/athletes/\`)

All geometry and textures in this folder are released under **CC0 1.0 Universal**.

- **MakeHuman assets** (base mesh, targets, eyes, eyebrows, eyelashes, teeth, proxies, skins): CC0 1.0,
  per MakeHuman's \`LICENSE.ASSETS.md\` and the per-asset \`license\` fields of the system-asset pack.
  - Repository \`${mh?.repo}\` at commit \`${mh?.commit}\` (${mh?.count} files, retrieved ${mh?.retrieved}).
  - System assets \`${sys?.url}\` (sha256 \`${sys?.sha256}\`, retrieved ${sys?.retrieved}).
  - Only asset data is used. No MakeHuman program code (AGPL) is used or shipped.
- **Toolchain-generated assets** (uniform, shoes, hair, gear, baked maps, conformed and re-topologized
  meshes): authored by the scripts in \`tools/athletes/\` and dedicated to the public domain under CC0 1.0.

No NBA, team, league or shoe-brand marks or real-person likenesses are included.

## Build tools (not shipped)

Blender ${lock.items.blender?.version} (GNU GPL) and KTX-Software ${lock.items.ktx?.version} (Apache-2.0) are used offline only.
Their output is not covered by their licenses.

## Basis Universal transcoder (\`public/basis/\`)

\`basis_transcoder.js\` and \`basis_transcoder.wasm\` are copied from three.js (\`examples/jsm/libs/basis\`),
built from Binomial's basis_universal, Apache License 2.0.

Full hashes of every input: \`sources.lock.json\`.
`,
)

// Basis transcoder for KTX2Loader
mkdirSync(PUBLIC_BASIS, { recursive: true })
for (const f of ['basis_transcoder.js', 'basis_transcoder.wasm']) copyFileSync(path.join(ROOT, 'node_modules', 'three', 'examples', 'jsm', 'libs', 'basis', f), path.join(PUBLIC_BASIS, f))

// delete files no longer referenced
const keep = new Set(['manifest.json', 'LICENSES.md', 'sources.lock.json'])
for (const lv of Object.values(manifest.levels)) {
  for (const a of Object.values(lv.assets)) keep.add(a.glb.file)
  for (const t of Object.values(lv.textures)) keep.add(t.file)
}
const walk = (dir) => (existsSync(dir) ? readdirSync(dir).flatMap((f) => (statSync(path.join(dir, f)).isDirectory() ? walk(path.join(dir, f)) : [path.join(dir, f)])) : [])
let removed = 0
for (const f of walk(PUBLIC_ATHLETES)) {
  if (!keep.has(rel(f))) {
    rmSync(f)
    removed++
  }
}

for (const [level, lv] of Object.entries(manifest.levels)) {
  const tris = Object.values(lv.assets).reduce((s, a) => s + a.triangles, 0)
  console.log(`[pack] ${level}: ${Object.keys(lv.assets).length} assets, ${Object.keys(lv.textures).length} textures, ${(lv.bytes / 1e6).toFixed(2)} MB, ${tris} triangles (all assets)`)
}
console.log(`[pack] manifest written${removed ? `, ${removed} stale files removed` : ''}`)
